<?php
// Reconcile existing workflow states only. Quantities and original movements stay untouched.
function ro_audit_plan(){
 $safe=[];$review=[];
 foreach(om_query("SELECT * FROM om_orders WHERE posting='Posted' AND (monitoring<>'Resolved' OR aftersales_resolution='Return Expected') ORDER BY id") as $o){
  if(!oa_deferred(oa_reported($o)['status']))continue;$t=rf_target(['platform'=>$o['platform'],'order'=>$o['order_no']]);$state=rf_state($t);$complete=oa_received_complete($o);$none=$state['receiving']==='No Physical Return';
  if($complete||$none){$row=['key'=>'O-'.$o['id'],'kind'=>'Order','id'=>(int)$o['id'],'label'=>$o['platform'].' / '.$o['order_no'],'reason'=>$complete?'Verified expected quantities already received':'Existing confirmed no-physical-return resolution','target'=>$complete?'Receipt Linked':'Refund Only','products'=>array_keys(om_existing_totals($o['id'])),'evidence'=>[$o['revision'],$o['aftersales_resolution'],$o['monitoring'],$state['receiving'],array_map(fn($r)=>[$r['id'],$r['qty']],$t['receipts']),array_map(fn($r)=>[$r['id'],$r['qty']],$t['legacy']),ri_scope($o)]];$row['fingerprint']=hash('sha256',json_encode($row));$safe[$row['key']]=$row;}
  else $review[]=['platform'=>$o['platform'],'order'=>$o['order_no'],'reason'=>$state['received_qty']?'Partial receiving — verify remaining items or an accepted short-shipment resolution':'Actual receipt or explicit no-return resolution is still required'];
 }
 foreach(om_query("SELECT n.*,p.master_sku FROM non_sellable n JOIN products p ON p.id=n.product_id WHERE n.qty>0 AND n.reversed_by_request IS NULL AND n.status IN ('For Review','Pending') ORDER BY n.id") as $n){
  if(packaging_kind($n['condition_type'])!=='damaged')continue;$row=['key'=>'N-'.$n['id'],'kind'=>'Non-Sellable','id'=>(int)$n['id'],'label'=>'NS-'.$n['id'].' · '.$n['master_sku'],'reason'=>'Damaged / Leak stock is already recorded; normalize misleading review label','target'=>'Recorded','products'=>[(int)$n['product_id']],'evidence'=>[$n['status'],$n['condition_type'],$n['qty'],$n['reversed_by_request'],release_total($n['id'])]];$row['fingerprint']=hash('sha256',json_encode($row));$safe[$row['key']]=$row;
 }
 return ['safe'=>$safe,'review'=>$review];
}
function ro_audit_digest($rows){return hash('sha256',json_encode(array_map(fn($r)=>[$r['key'],$r['fingerprint']],array_values($rows))));}
function ro_audit_apply($ids,$digest,$ack){
 rf_require(true);if(!in_array(access_profile(),['Admin','Operations Lead'],true))throw new Exception('Admin or Operations Lead is required for existing-data reconciliation.');if(!$ack)throw new Exception('Review the evidence and confirm that no stock quantities will change.');
 if(!is_array($ids)||!$ids||count($ids)>50||count(array_unique($ids))!==count($ids))throw new Exception('Select 1 to 50 verified records.');$plan=ro_audit_plan();$chosen=[];$products=[];
 foreach($ids as $key){if(!is_string($key)||!isset($plan['safe'][$key]))throw new Exception('Audit evidence changed. Refresh before applying.');$chosen[$key]=$plan['safe'][$key];$products=array_merge($products,$chosen[$key]['products']);}
 if(!is_string($digest)||!hash_equals(ro_audit_digest($chosen),$digest))throw new Exception('Audit evidence changed. Review the latest records.');
 return process_transaction(function()use($chosen,$products){$products=array_unique($products);sort($products,SORT_NUMERIC);foreach($products as $pid)om_query('SELECT id FROM products WHERE id=? FOR UPDATE',[$pid])->fetch();foreach($chosen as $row)om_query('SELECT id FROM '.($row['kind']==='Order'?'om_orders':'non_sellable').' WHERE id=? FOR UPDATE',[$row['id']])->fetch();
  unset($GLOBALS['RF_JOURNAL'],$GLOBALS['RI_SCOPES'],$GLOBALS['OA_REPORTS']);$fresh=ro_audit_plan();foreach($chosen as $key=>$row)if(!isset($fresh['safe'][$key])||!hash_equals($row['fingerprint'],$fresh['safe'][$key]['fingerprint']))throw new Exception('Existing records changed. No reconciliation was applied. Refresh the audit.');
  foreach($chosen as $row){if($row['kind']==='Order'){$o=om_order($row['id']);if($row['target']==='Receipt Linked')oa_receipt_reconcile($o['platform'],$o['order_no']);else om_query("UPDATE om_orders SET monitoring='Resolved',exception_text='',revision=revision+1 WHERE id=?",[$o['id']]);om_query('UPDATE om_alerts SET resolved=1 WHERE order_id=?',[$o['id']]);om_event($o['id'],null,'Existing return workflow reconciled',['reason'=>$row['reason'],'stock_changed'=>false,'evidence_fingerprint'=>$row['fingerprint']]);}
   else{om_query("UPDATE non_sellable SET status='Recorded' WHERE id=?",[$row['id']]);audit('Normalize damaged stock workflow','Non-Sellable',$row['label'],json_encode(['previous_status'=>$row['evidence'][0],'new_status'=>'Recorded','stock_changed'=>false]));}}
  audit('Reconcile existing return workflows','Return','Existing Data',count($chosen).' verified records; stock quantities and original movements unchanged.');return count($chosen);
 });
}
function ro_audit_page(){
 rf_require();$plan=ro_audit_plan();$batch=array_slice($plan['safe'],0,50,true);
 echo '<div class="page-head"><div><a class="back" href="?page=return_followup">← Return Cases</a><h1>Existing Returns · Data Review</h1><p>Resolve verified existing records without receiving or adding stock again.</p></div></div><section class="card"><h3>'.count($plan['safe']).' Verified Records Ready</h3><p class="muted small">Complete posted returns and existing no-return outcomes can be reconciled. Misleading Damaged / Leak review labels are normalized to Recorded. Original transactions and quantities remain unchanged.</p>';
 if($batch){echo '<table class="table"><tr><th>Record</th><th>Verified Basis</th><th>Result</th></tr>';foreach($batch as $row)echo '<tr><td>'.e($row['label']).'</td><td>'.e($row['reason']).'</td><td>'.e($row['target']==='Recorded'?'Recorded · Non-Sellable':'Resolved').'</td></tr>';echo '</table>';if(in_array(access_profile(),['Admin','Operations Lead'],true)){echo '<form method="post" action="actions.php" class="stack" data-confirm="Reconcile these verified existing records? No quantities or stock movements will be changed.">';workflow_hidden('receiving_reconcile_existing',['record_keys'=>json_encode(array_keys($batch)),'audit_digest'=>ro_audit_digest($batch),'return'=>'return_operations_audit']);echo '<label class="ack"><input type="checkbox" name="audit_ack" value="1" required> I reviewed these existing records. No items will be received or credited again.</label><button class="btn primary">Resolve '.count($batch).' Verified Records</button></form>';}}
 else echo '<p>No verified workflow corrections remain.</p>';echo '</section><section class="card table-wrap"><h3>'.count($plan['review']).' Cases Still Need Verification</h3><p class="muted small">These are kept open. A partial receipt or unposted physical item is not automatically treated as a completed return.</p><table class="table"><tr><th>Platform / Order</th><th>Next Step</th><th>Action</th></tr>';foreach(array_slice($plan['review'],0,50) as $r)echo '<tr><td>'.e($r['platform'].' / '.$r['order']).'</td><td>'.e($r['reason']).'</td><td>'.rf_link($r['platform'],$r['order']).'</td></tr>';if(!$plan['review'])echo '<tr><td colspan="3">No unresolved receiving cases in this review.</td></tr>';echo '</table></section>';
}
